LEGACY_REWARD_TYPES = {
    "download": "download_bonus",
    "points": "credits",
    "ad_free": "ad_free",
}


def adopt_server_validated_flow(apps, _schema_editor):
    """Map legacy reward types; unmapped ones become disabled credit rewards.

    Legacy 'started' rows can never complete under the token flow, so they are closed
    before the one-active-view-per-user constraint is created.
    """
    Config = apps.get_model("ads", "RewardedAdConfig")
    View = apps.get_model("ads", "RewardedAdView")
    for config in Config.objects.all():
        mapped = LEGACY_REWARD_TYPES.get(config.reward_type)
        if mapped is None:
            config.reward_type = "credits"
            config.is_enabled = False
        else:
            config.reward_type = mapped
        config.save(update_fields=["reward_type", "is_enabled"])
    View.objects.filter(status="started").update(status="expired")


